pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deploy, set MinSum to 1 ether, initialize, then put 1 ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);

        // Set MinSum (reference sets it to 1 ether, buggy leaves it at 0)
        c.SetMinSum(1 ether);
        // Initialize so SetMinSum can't be called again
        c.Initialized();

        // User puts 1 ether with lock time 0 so unlock immediately
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        // Now call Collect(1 ether)
        // In reference: MinSum == 1 ether, acc.balance >= MinSum (1 >= 1), so sends ether
        // In buggy: MinSum == 0, condition acc.balance >= MinSum holds (1 >= 0) but lockTime condition fails? No, lockTime satisfied. Actually bug: MinSum never set, stays 0; original check: acc.balance >= MinSum && acc.balance >= _am && timestamp > unlockTime. With MinSum=0, first condition holds. But we need divergence. The difference is MinSum value after Collect. Let's read MinSum after the call.

        try c.Collect(1 ether) {
            // Call succeeded, now check MinSum
            // Reference: SetMinSum(1 ether) set MinSum to 1 ether, unchanged by Collect
            // Buggy: SetMinSum did nothing, so MinSum remains 0
            assertTrue(c.MinSum() == 1 ether, "Reference: MinSum should be 1 ether");
        } catch {
            // If it reverts, we also check MinSum (should be 0 in buggy)
            assertTrue(c.MinSum() == 0, "Buggy: MinSum should be 0");
        }
    }
}

