pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract (sets initialized = true)
        c.Initialized();
        // Step 2: Attempt to set MinSum to 10. In reference, this reverts (MinSum stays 0).
        // In bug, it succeeds (MinSum becomes 10).
        // We try-catch to bypass revert, but we don't need to catch here; we just call.
        // Actually, we need to handle the revert in the reference. We'll call and let it revert,
        // but then we won't reach further steps. So we must wrap the SetMinSum call to continue.
        bool setMinSumSucceeded = true;
        try c.SetMinSum(10) {
            // succeeded (bug)
        } catch {
            setMinSumSucceeded = false;
        }
        // Step 3: Fund a user and call Put with 9 wei
        address user = address(0x123);
        vm.deal(user, 9 ether);
        vm.prank(user);
        c.Put{value: 9 ether}(0);
        // Step 4: Try Collect(9 ether). In reference, unchanged MinSum=0, so Collect succeeds.
        // In bug, MinSum=10, so Collect reverts.
        bool collectSucceeded = true;
        vm.prank(user);
        try c.Collect(9 ether) {
            // succeeded (reference)
        } catch {
            collectSucceeded = false;
        }
        // Assert: In reference, collect succeeded and contract balance became 0.
        // In bug, collect failed and contract balance is 9 ether.
        // We assert that address(c).balance == 0 only if the reference path was taken.
        // But we need a single assertion that reference holds and bug breaks.
        // Reference: collectSucceeded == true, balance == 0.
        // Bug: collectSucceeded == false, balance == 9 ether.
        // We assert that collectSucceeded == true. This holds for reference (since MinSum=0 < balance=9)
        // and fails for bug (since MinSum=10 > balance=9).
        assertTrue(collectSucceeded);
    }
}

