pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: deployer = address(this), use a separate caller
        address caller = address(0x1234);

        // Step 1: Initialize the contract (both reference and buggy start here)
        c.Initialized();

        // Step 2: In reference, SetMinSum(10) reverts; we call it anyway - in reference it will revert, in bug it won't
        // We need to capture the revert. We'll call it directly - in reference it reverts, keeping MinSum=0;
        // in bug it succeeds, setting MinSum=10. We don't need to catch revert here; we just observe the final state.
        // Call SetMinSum(10) - reference reverts (stays 0), bug succeeds (becomes 10)
        (bool successSetMinSum, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 10));
        // In reference, successSetMinSum = false; in bug, true.
        // But we don't assert on that; we just need the state difference.

        // Step 3: Fund caller, Put(0) with 9 wei
        vm.deal(caller, 9 ether);
        vm.prank(caller);
        c.Put{value: 9 ether}(0);  // acc.balance = 9 eth

        // Step 4: Now attempt Collect(9) - this will revert if MinSum > 9 (i.e., bug) or succeed if MinSum <= 9 (reference)
        // Wrap in try/catch to capture revert
        bool collectSucceeded;
        vm.prank(caller);
        try c.Collect(9 ether) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // Final assertion:
        // In reference: MinSum=0, so Collect succeeds, sends 9 eth, contract balance = 0
        // In bug: MinSum=10, so Collect reverts, contract balance = 9
        assertTrue((address(c).balance == 0 ether) == collectSucceeded, "Balance or success mismatch");
        // More precisely: In reference, collectSucceeded is true and balance=0; in bug, collectSucceeded is false and balance=9.
        // The assertion: (balance == 0) should equal collectSucceeded (true/true for ref, false/false for bug).
    }
}

