// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up initial state: SetMinSum(500), Initialized()
        c.SetMinSum(500);
        c.Initialized();
        // Fund the contract (and msg.sender) for the Put call
        vm.deal(address(this), 1000);
        // Put 1000 wei with lockTime=0 so unlockTime = block.timestamp
        c.Put{value: 1000}(0);
        // Warp past unlockTime (block.timestamp is 0 initially, so just warp to 1)
        vm.warp(1);
        // Now try Collect(500) - this will revert in M because lock is never released
        // In M, after the outer call returns, locked_ remains true;
        // but the outer call already reverted because Collect's internal call reenters?
        // Actually in M, the reentrancy lock is not released, so a second call to Collect would revert.
        // But in this single call sequence, after Collect succeeds in P, the reentrancy lock is released.
        // To observe divergence, we need a state variable that differs after the call.
        // The difference: In P, Collect deducts 500, so c.Acc(address(this)).balance == 500.
        // In M, Collect reverts because of require(!locked_)? 
        // Wait - the first call Collect is fine (locked_ becomes true, then does its work).
        // The lock not being released only affects subsequent nonReentrant_ calls.
        // So after one Collect, the lock is still true in M, preventing any future nonReentrant_ calls.
        // So we call Collect, then try another nonReentrant_ call (e.g., SetMinSum) to see divergence.
        // But SetMinSum reverts if initialized is true, which it is.
        // We can call Initialized again (but it's already true, but still guarded).
        // Let's try: after Collect, call Put with lockTime=0 and value=1 (should succeed in P, revert in M).
        // Then check that MinSum is unchanged (500) and balance differs.
        // Simpler: just check that a second nonReentrant_ call reverts in M but not in P.
        // But assertTrue expects a boolean about state, not a revert.
        // Use try/catch on a call that should succeed in P but revert in M.
        bool ok;
        // First call Collect to trigger the lock
        c.Collect(500);
        // Now try Put again (nonReentrant_ guarded) - should succeed in P, revert in M
        vm.deal(address(this), 1);
        try c.Put{value: 1}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // In P, lock is released so Put succeeds -> ok == true
        // In M, lock is stuck -> Put reverts -> ok == false
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deployer funds the contract and configures MinSum and LogFile
        vm.deal(address(this), 1 ether);
        c.SetMinSum(500);
        c.SetLogFile(address(0xdead));
        c.Initialized();
        // Deposit 1000 wei via Put, with lockTime 0 so unlockTime = block.timestamp
        c.Put{value: 1000}(0);
        // Warp past unlockTime
        vm.warp(block.timestamp + 1);
        // First Collect(500): succeeds in both reference and buggy, deducts 500
        c.Collect(500);
        // Now: reference lock released, buggy lock still active.
        // Second Collect(500): reference succeeds, buggy reverts because nonReentrant locked
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        // Transfer ownership of the remaining balance to attacker (impossible directly, but we can use a separate call)
        // Instead, we test that after first Collect, the lock differs; we call another nonReentrant function to observe.
        // After first Collect, buggy lock is still true, so a second Collect from another user will revert.
        // The reference will succeed.
        vm.startPrank(attacker);
        // attacker deposits nothing, just tries to Collect (balance 0, MinSum 500) – will revert due to balance check,
        // but that revert is not due to lock. So we need attacker to have sufficient balance.
        // Actually, attacker can call SetMinSum (nonReentrant) – but that reverts if intitalized? No, SetMinSum reverts only if initialized is false? Wait: SetMinSum reverts if intitalized is true? The code: if(intitalized)revert(); So after Initialized(), SetMinSum always reverts.
        // We need a function that is nonReentrant and does not revert after initialization. Let's use Collect with sufficient balance. So give attacker balance.
        vm.stopPrank();
        // Give attacker deposit
        vm.prank(attacker);
        c.Put{value: 1000}(0);
        vm.warp(block.timestamp + 1);
        vm.prank(attacker);
        // This second Collect should succeed in reference, revert in buggy due to lock.
        // Use try/catch to detect revert.
        bool ok;
        try c.Collect(500) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: lock released, so Collect succeeds (ok=true). Buggy: lock stuck, so Collect reverts (ok=false).
        assertTrue(ok == true);
    }
}

