pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address caller = address(0x1234);
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup initial state
        vm.deal(caller, 1000 ether);

        // Call Initialized() to make the contract active
        vm.prank(caller);
        c.Initialized();

        // Set MinSum to 500
        vm.prank(caller);
        c.SetMinSum(500);

        // Deposit 1000 wei
        vm.prank(caller);
        c.Put{value: 1000}(1 days);

        // Warp past unlockTime (block.timestamp + 1 days)
        vm.warp(block.timestamp + 2 days);

        // Now call Collect(500) – this should succeed in reference, revert in buggy due to lock not released
        // In the reference, the external call succeeds, balance reduces to 500.
        // In the buggy version, the collector's call reverts, balance remains 1000.
        vm.prank(caller);
        c.Collect(500);

        // The assertion: reference passes because balance is 500; buggy fails because balance is 1000
        assertTrue(c.Acc(caller).balance == 500, "Balance should be 500 after Collect");
    }
