        c.Collect(1);
        // Assert: in reference balance is 1 ether - 1 wei, in buggy it's 2 ether - 1 wei
        // We can read balance via the getter
        ( , uint bal) = c.Acc(address(reenter));
        assertTrue(bal == 1 ether - 1 wei);
    }
}

contract Reenter {
    C c;
    bool public shouldReenter;
    constructor(address _c) { c = C(_c); shouldReenter = true; }
    function callPut(uint _lockTime) external payable {
        c.Put{value: msg.value}(_lockTime);
    }
    receive() external payable {
        if (shouldReenter) {
            shouldReenter = false;
            c.Put{value: msg.value}(0);
        }
    }
}

