pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 wei
        c.SetMinSum(1);
        c.Initialized();
        // Set a dummy LogFile address to avoid revert
        vm.deal(address(0x789), 1 ether);
        vm.prank(address(0x789));
        c.SetLogFile(address(0xdead));

        // User puts 1 wei with lockTime 0
        address user = address(0x123);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.Put{value: 1 wei}(0);

        // Warp past unlockTime (block.timestamp + 0 <= acc.unlockTime after Put sets unlockTime to block.timestamp)
        vm.warp(block.timestamp + 1);

        // User collects 1 wei
        vm.prank(user);
        c.Collect(1 wei);

        // Assert that Log History length is 2 in reference (Put + Collect) but only 1 in mutant (only Collect)
        uint256 historyLength = c.HistoryLength();
        assertTrue(historyLength == 2, "Log History length should be 2 in reference");
    }
}

